<?php use App\Support\Helpers; ?>
<h1>Configuración de columnas</h1><?php if ($flash): ?><p class="alert success"><?= Helpers::h($flash) ?></p><?php endif; ?><form method="post" action="/admin/columns"><input type="hidden" name="csrf" value="<?= Helpers::h($csrf) ?>"><div class="table-wrap"><table class="admin-table"><thead><tr><th>Original</th><th>Alias</th><th>Detectado</th><th>Tipo manual</th><th>Formato</th><th>Tabla</th><th>Detalle</th><th>Orden</th><th>Estado</th></tr></thead><tbody><?php foreach ($columns as $column): ?><tr><?php $id=(int)$column['id']; ?><td><?= Helpers::h($column['original_name']) ?></td><td><input name="columns[<?= $id ?>][alias]" value="<?= Helpers::h($column['alias']) ?>"></td><td><?= Helpers::h($column['detected_type']) ?></td><td><select name="columns[<?= $id ?>][manual_type]"><option value="">Automático</option><?php foreach (['text'=>'Texto','integer'=>'Entero','decimal'=>'Decimal','date'=>'Fecha','datetime'=>'Fecha y hora','boolean'=>'Booleano'] as $value=>$label): ?><option value="<?= $value ?>" <?= $column['manual_type']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></td><td><input name="columns[<?= $id ?>][display_format]" value="<?= Helpers::h($column['display_format']) ?>" placeholder="Opcional"></td><td><input type="checkbox" name="columns[<?= $id ?>][visible_table]" <?= $column['visible_table']?'checked':'' ?>></td><td><input type="checkbox" name="columns[<?= $id ?>][visible_detail]" <?= $column['visible_detail']?'checked':'' ?>></td><td><input type="number" min="0" name="columns[<?= $id ?>][display_order]" value="<?= $column['display_order'] ?>"></td><td><?= $column['present_in_last_import'] ? 'Presente' : 'Histórica' ?></td></tr><?php endforeach; ?></tbody></table></div><button>Guardar cambios</button></form>
